// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 管理精选缓存
	// (GET /v1/admin/cache)
	ListCacheEntries(ctx context.Context, request ListCacheEntriesRequestObject) (ListCacheEntriesResponseObject, error)
	// 人工创建精选候选
	// (POST /v1/admin/cache)
	ProposeCacheEntry(ctx context.Context, request ProposeCacheEntryRequestObject) (ProposeCacheEntryResponseObject, error)
	// 缓存阈值校准
	// (GET /v1/admin/cache-calibration)
	ReadCacheCalibration(ctx context.Context, request ReadCacheCalibrationRequestObject) (ReadCacheCalibrationResponseObject, error)
	// 批准缓存公开内容
	// (POST /v1/admin/cache/{cacheId}/approve)
	ApproveCacheEntry(ctx context.Context, request ApproveCacheEntryRequestObject) (ApproveCacheEntryResponseObject, error)
	// 人工停用缓存
	// (POST /v1/admin/cache/{cacheId}/disable)
	DisableCacheEntry(ctx context.Context, request DisableCacheEntryRequestObject) (DisableCacheEntryResponseObject, error)
	// 隔离管理诊断
	// (POST /v1/admin/debug-turns)
	CreateDebugTurn(ctx context.Context, request CreateDebugTurnRequestObject) (CreateDebugTurnResponseObject, error)
	// 读取管理诊断
	// (GET /v1/admin/debug-turns/{debugId})
	ReadDebugTurn(ctx context.Context, request ReadDebugTurnRequestObject) (ReadDebugTurnResponseObject, error)
	// 读取问答策略
	// (GET /v1/admin/policy)
	ReadQaPolicy(ctx context.Context, request ReadQaPolicyRequestObject) (ReadQaPolicyResponseObject, error)
	// 管理公开问答策略
	// (PUT /v1/admin/policy)
	PutQaPolicy(ctx context.Context, request PutQaPolicyRequestObject) (PutQaPolicyResponseObject, error)
	// 浏览与筛选问答记录
	// (GET /v1/admin/turns)
	ListTurnRecords(ctx context.Context, request ListTurnRecordsRequestObject) (ListTurnRecordsResponseObject, error)
	// 查看问答记录
	// (GET /v1/admin/turns/{turnId})
	ReadTurnRecord(ctx context.Context, request ReadTurnRecordRequestObject) (ReadTurnRecordResponseObject, error)
	// 取得本地维护屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放已授权维护屏障
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 创建伪名访客会话
	// (POST /v1/conversations)
	CreateConversation(ctx context.Context, request CreateConversationRequestObject) (CreateConversationResponseObject, error)
	// 删除自有对话数据
	// (DELETE /v1/conversations/{conversationId})
	DeleteConversation(ctx context.Context, request DeleteConversationRequestObject) (DeleteConversationResponseObject, error)
	// 读取自有访客历史
	// (GET /v1/conversations/{conversationId})
	GetConversation(ctx context.Context, request GetConversationRequestObject) (GetConversationResponseObject, error)
	// 读取缓存翻译的当前权威基准材料
	// (GET /v1/internal/cache/{cacheId}/translation-source)
	ReadCacheTranslationSource(ctx context.Context, request ReadCacheTranslationSourceRequestObject) (ReadCacheTranslationSourceResponseObject, error)
	// 免费读取公开问答入口配置能力
	// (GET /v1/public-capabilities)
	ReadPublicCapability(ctx context.Context, request ReadPublicCapabilityRequestObject) (ReadPublicCapabilityResponseObject, error)
	// 访客全文搜索（关键词与向量混合检索）
	// (POST /v1/search)
	SearchDocuments(ctx context.Context, request SearchDocumentsRequestObject) (SearchDocumentsResponseObject, error)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(ctx context.Context, request ReadSnapshotArchiveRequestObject) (ReadSnapshotArchiveResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出安全watermark快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
	// 准入后开始问答轮次
	// (POST /v1/turns)
	StartTurn(ctx context.Context, request StartTurnRequestObject) (StartTurnResponseObject, error)
	// 取消问答及所有子调用
	// (POST /v1/turns/{turnId}/cancel)
	CancelTurn(ctx context.Context, request CancelTurnRequestObject) (CancelTurnResponseObject, error)
	// SSE断线重连
	// (GET /v1/turns/{turnId}/events)
	ResumeAnswerStream(ctx context.Context, request ResumeAnswerStreamRequestObject) (ResumeAnswerStreamResponseObject, error)
	// 保存访客单条反馈
	// (PUT /v1/turns/{turnId}/feedback)
	RecordFeedback(ctx context.Context, request RecordFeedbackRequestObject) (RecordFeedbackResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

